import { test, expect, Page } from '@playwright/test';

// Fully visible cards (1-based, DOM order) as "min-max", e.g. "1-2"; "" if none.
async function visibleRange(page: Page): Promise<string> {
  return page.locator('article').first().evaluate((first) => {
    const c = first.parentElement!;
    let box = c as HTMLElement;
    while (box && box.scrollWidth <= box.clientWidth && box.parentElement) box = box.parentElement;
    const r = box.getBoundingClientRect();
    const idx = Array.from(c.children)
      .map((el, i) => ({ b: el.getBoundingClientRect(), i: i + 1 }))
      .filter(({ b }) => b.left >= r.left - 2 && b.right <= r.right + 2)
      .map(({ i }) => i);
    return idx.length ? `${Math.min(...idx)}-${Math.max(...idx)}` : '';
  });
}
const parse = (s: string) => s.split('-').map(Number);

test.describe('Landing testimonials carousel', () => {
  test('Next and Previous move exactly one card (ar) @prod-safe (#c8f678)', async ({ page }) => {
    // 1. Open the home page as guest (ar).
    await page.goto('/ar');

    // 2. Scroll to the testimonials section.
    const heading = page.getByRole('heading', { name: 'مستخدمو Hunters يشاركون تجربتهم' });
    await heading.scrollIntoViewIfNeeded();
    await expect(heading).toBeVisible();

    const total = await page.locator('article').count();
    expect(total).toBeGreaterThan(1);
    const next = page.getByRole('button', { name: 'التالي', exact: true });
    const prev = page.getByRole('button', { name: 'السابق', exact: true });

    // Expected: start shows card 1; Previous disabled, Next enabled.
    await expect.poll(() => visibleRange(page)).toMatch(/^1-/);
    await expect(prev).toBeDisabled();
    await expect(next).toBeEnabled();

    // 3. Next until disabled: every press moves forward by at most one card, no card is skipped.
    const seen = new Set<number>();
    let state = await visibleRange(page);
    for (let k = parse(state)[0]; k <= parse(state)[1]; k++) seen.add(k);
    for (let p = 1; p <= total + 1 && (await next.isEnabled()); p++) {
      const before = state;
      await next.click();
      await expect.poll(() => visibleRange(page), { message: `Next press ${p}: carousel did not move` }).not.toBe(before);
      state = await visibleRange(page);
      const [a0, b0] = parse(before); const [a1, b1] = parse(state);
      expect(a1 - a0, `Next press ${p}: first visible card jumped (${before} → ${state})`).toBeLessThanOrEqual(1);
      expect(b1 - b0, `Next press ${p}: last visible card jumped (${before} → ${state})`).toBeLessThanOrEqual(1);
      expect(a1, `Next press ${p}: moved backwards`).toBeGreaterThanOrEqual(a0);
      for (let k = a1; k <= b1; k++) seen.add(k);
    }
    await expect(next).toBeDisabled();
    await expect(prev).toBeEnabled();
    expect([...seen].sort((x, y) => x - y), 'every card was fully shown').toEqual(Array.from({ length: total }, (_, i) => i + 1));
    expect(parse(state)[1]).toBe(total);

    // 4. Previous until disabled: every press moves back by at most one card, ends at card 1.
    for (let p = 1; p <= total + 1 && (await prev.isEnabled()); p++) {
      const before = state;
      await prev.click();
      await expect.poll(() => visibleRange(page), { message: `Previous press ${p}: carousel did not move` }).not.toBe(before);
      state = await visibleRange(page);
      const [a0, b0] = parse(before); const [a1, b1] = parse(state);
      expect(a0 - a1, `Previous press ${p}: jumped (${before} → ${state})`).toBeLessThanOrEqual(1);
      expect(b0 - b1, `Previous press ${p}: jumped (${before} → ${state})`).toBeLessThanOrEqual(1);
      expect(a1, `Previous press ${p}: moved forward`).toBeLessThanOrEqual(a0);
    }
    await expect(prev).toBeDisabled();
    await expect(next).toBeEnabled();
    expect(parse(state)[0]).toBe(1);
  });
});
